1	//! Translate core `Item`s into Gemini `contents` + `systemInstruction`.
2	
3	use paigasus_helikon_core::{ContentPart, Item, MediaSource, ModelError};
4	use serde_json::{json, Value};
5	
6	/// `contents` + optional `systemInstruction`.
7	pub(crate) struct TranslatedContents {
8	    pub(crate) system: Option<Value>,
9	    pub(crate) contents: Vec<Value>,
10	}
11	
12	/// Translate core items into Gemini `contents`. Returns an error on an empty
13	/// or system-only conversation (Gemini 400s on empty contents).
14	pub(crate) fn items_to_contents(items: &[Item]) -> Result<TranslatedContents, ModelError> {
15	    // Build call_id -> name map from all tool calls (ToolResult has no name).
16	    let mut call_names: std::collections::HashMap<&str, &str> = std::collections::HashMap::new();
17	    for it in items {
18	        match it {
19	            Item::ToolCall { call_id, name, .. } => {
20	                call_names.insert(call_id.as_str(), name.as_str());
21	            }
22	            Item::AssistantMessage { content, .. } => {
23	                for p in content {
24	                    if let ContentPart::ToolUse { call_id, name, .. } = p {
25	                        call_names.insert(call_id.as_str(), name.as_str());
26	                    }
27	                }
28	            }
29	            _ => {}
30	        }
31	    }
32	
33	    let mut system_parts: Vec<Value> = Vec::new();
34	    let mut contents: Vec<Value> = Vec::new();
35	
36	    for it in items {
37	        match it {
38	            Item::System { content } => {
39	                system_parts.extend(text_parts(content));
40	            }
41	            Item::UserMessage { content } => {
42	                let parts = user_parts(content, &call_names)?;
43	                // A UserMessage carrying only a ToolResult becomes one
44	                // functionResponse part (non-empty); guard anyway so a
45	                // genuinely empty turn is dropped rather than emitting
46	                // `"parts": []`.
47	                if !parts.is_empty() {
48	                    contents.push(json!({ "role": "user", "parts": parts }));
49	                }
50	            }
51	            Item::AssistantMessage { content, .. } => {
52	                contents.push(json!({ "role": "model", "parts": assistant_parts(content) }));
53	            }
54	            Item::ToolCall {
55	                call_id,
56	                name,
57	                args,
58	            } => {
59	                contents.push(json!({
60	                    "role": "model",
61	                    "parts": [ { "functionCall": { "id": call_id, "name": name, "args": args } } ]
62	                }));
63	            }
64	            Item::ToolResult { call_id, content } => {
65	                let name = call_names.get(call_id.as_str()).ok_or_else(|| {
66	                    ModelError::Other(anyhow::anyhow!(
67	                        "tool result references unknown call_id {call_id}"
68	                    ))
69	                })?;
70	                contents.push(json!({
71	                    "role": "user",
72	                    "parts": [ {
73	                        "functionResponse": {
74	                            "id": call_id,
75	                            "name": name,
76	                            "response": tool_response_object(content),
77	                        }
78	                    } ]
79	                }));
80	            }
81	            _ => {}
82	        }
83	    }
84	
85	    if contents.is_empty() {
86	        return Err(ModelError::Other(anyhow::anyhow!(
87	            "gemini request has no user/model turns (empty or system-only conversation)"
88	        )));
89	    }
90	
91	    let system = (!system_parts.is_empty()).then(|| json!({ "parts": system_parts }));
92	    Ok(TranslatedContents { system, contents })
93	}
94	
95	fn text_parts(content: &[ContentPart]) -> Vec<Value> {
96	    content
97	        .iter()
98	        .filter_map(|p| match p {
99	            ContentPart::Text { text } => Some(json!({ "text": text })),
100	            _ => None,
101	        })
102	        .collect()
103	}
104	
105	/// Translate the parts of an `Item::UserMessage`.
106	///
107	/// Handles the Anthropic-native [`ContentPart::ToolResult`] shape (a tool
108	/// result carried inside a user turn) by emitting a `functionResponse` part,
109	/// recovering the function name from `call_names` exactly like the top-level
110	/// [`Item::ToolResult`] branch. Text and base64 images translate as usual;
111	/// URL images and other parts are dropped with a discriminant warning.
112	fn user_parts(
113	    content: &[ContentPart],
114	    call_names: &std::collections::HashMap<&str, &str>,
115	) -> Result<Vec<Value>, ModelError> {
116	    let mut out = Vec::new();
117	    for p in content {
118	        match p {
119	            ContentPart::Text { text } => out.push(json!({ "text": text })),
120	            ContentPart::Image {
121	                source: MediaSource::Base64 { mime_type, data },
122	            } => {
123	                out.push(json!({ "inlineData": { "mimeType": mime_type, "data": data } }));
124	            }
125	            ContentPart::ToolResult { call_id, content } => {
126	                let name = call_names.get(call_id.as_str()).ok_or_else(|| {
127	                    ModelError::Other(anyhow::anyhow!(
128	                        "tool result references unknown call_id {call_id}"
129	                    ))
130	                })?;
131	                out.push(json!({
132	                    "functionResponse": {
133	                        "id": call_id,
134	                        "name": name,
135	                        "response": tool_response_object(content),
136	                    }
137	                }));
138	            }
139	            other => {
140	                tracing::warn!(
141	                    target: "paigasus::gemini::translate",
142	                    part = ?std::mem::discriminant(other),
143	                    "unsupported content part; skipping"
144	                );
145	            }
146	        }
147	    }
148	    Ok(out)
149	}
150	
151	fn assistant_parts(content: &[ContentPart]) -> Vec<Value> {
152	    let mut out = Vec::new();
153	    for p in content {
154	        match p {
155	            ContentPart::Text { text } => out.push(json!({ "text": text })),
156	            ContentPart::ToolUse {
157	                call_id,
158	                name,
159	                args,
160	            } => {
161	                out.push(json!({ "functionCall": { "id": call_id, "name": name, "args": args } }));
162	            }
163	            ContentPart::Reasoning { .. } => { /* deferred (D3) */ }
164	            other => {
165	                tracing::warn!(
166	                    target: "paigasus::gemini::translate",
167	                    part = ?std::mem::discriminant(other),
168	                    "unsupported assistant part; skipping"
169	                );
170	            }
171	        }
172	    }
173	    out
174	}
175	
176	/// Reduce a tool result's content parts to a JSON object for `functionResponse.response`.
177	fn tool_response_object(content: &[ContentPart]) -> Value {
178	    let text: String = content
179	        .iter()
180	        .filter_map(|p| match p {
181	            ContentPart::Text { text } => Some(text.as_str()),
182	            _ => None,
183	        })
184	        .collect::<Vec<_>>()
185	        .join("");
186	    match serde_json::from_str::<Value>(&text) {
187	        Ok(Value::Object(m)) => Value::Object(m),
188	        Ok(other) => json!({ "result": other }),
189	        Err(_) => json!({ "result": text }),
190	    }
191	}
