1	//! `GeminiModel` — public [`paigasus_helikon_core::Model`] implementation.
2	
3	use std::sync::Arc;
4	
5	use async_stream::stream;
6	use async_trait::async_trait;
7	use eventsource_stream::Eventsource;
8	use futures_core::stream::BoxStream;
9	use futures_util::StreamExt;
10	use paigasus_helikon_core::{
11	    CancellationToken, Model, ModelCapabilities, ModelError, ModelEvent, ModelRequest,
12	};
13	
14	use crate::auth::Auth;
15	use crate::builder::{BuildError, Config, GeminiModelBuilder, Transport};
16	use crate::error::{classify, parse_retry_after_ms};
17	use crate::sse::GeminiChunk;
18	use crate::stream::StreamTranslator;
19	use crate::transport::{auth_header, stream_url};
20	
21	/// Google Gemini provider (Developer API + Vertex).
22	#[derive(Debug, Clone)]
23	pub struct GeminiModel(pub(crate) Arc<Config>);
24	
25	impl GeminiModel {
26	    /// Developer-API builder (API key).
27	    pub fn developer(model_id: impl Into<String>) -> GeminiModelBuilder {
28	        GeminiModelBuilder::new(model_id, Transport::Developer)
29	    }
30	    /// Vertex-AI builder (project + location + bearer/token-provider).
31	    pub fn vertex(
32	        model_id: impl Into<String>,
33	        project: impl Into<String>,
34	        location: impl Into<String>,
35	    ) -> GeminiModelBuilder {
36	        GeminiModelBuilder::new(
37	            model_id,
38	            Transport::Vertex {
39	                project: project.into(),
40	                location: location.into(),
41	            },
42	        )
43	    }
44	    /// Developer API from `GEMINI_API_KEY` (fallback `GOOGLE_API_KEY`).
45	    pub fn from_env(model_id: impl Into<String>) -> Result<Self, BuildError> {
46	        let key = std::env::var("GEMINI_API_KEY")
47	            .or_else(|_| std::env::var("GOOGLE_API_KEY"))
48	            .map_err(|_| BuildError::MissingApiKey)?;
49	        Self::developer(model_id).api_key(key).build()
50	    }
51	
52	    /// Vertex AI from the ambient environment, authenticating via Application
53	    /// Default Credentials (ADC).
54	    ///
55	    /// Reads `GOOGLE_CLOUD_PROJECT` (required) and `GOOGLE_CLOUD_LOCATION`
56	    /// (defaults to `global`), then discovers ADC credentials through
57	    /// [`crate::AdcTokenProvider`]. Enabled by the `vertex-adc` cargo feature.
58	    #[cfg(feature = "vertex-adc")]
59	    pub async fn vertex_from_env(model_id: impl Into<String>) -> Result<Self, BuildError> {
60	        let project =
61	            std::env::var("GOOGLE_CLOUD_PROJECT").map_err(|_| BuildError::MissingVertexProject)?;
62	        let location =
63	            std::env::var("GOOGLE_CLOUD_LOCATION").unwrap_or_else(|_| "global".to_owned());
64	        let provider = crate::auth::AdcTokenProvider::from_env()
65	            .await
66	            .map_err(|e| BuildError::Adc(e.to_string()))?;
67	        Self::vertex(model_id, project, location)
68	            .token_provider(provider)
69	            .build()
70	    }
71	
72	    pub(crate) fn from_config(cfg: Config) -> Self {
73	        Self(Arc::new(cfg))
74	    }
75	}
76	
77	#[async_trait]
78	impl Model for GeminiModel {
79	    async fn invoke(
80	        &self,
81	        request: ModelRequest,
82	        cancel: CancellationToken,
