        .invoke(user("Say hi in one word."), CancellationToken::new())
        .await
        .unwrap();
    let mut got_text = false;
    while let Some(ev) = s.next().await {
        if let Ok(ModelEvent::TokenDelta { .. }) = ev {
            got_text = true;
        }
    }
